from pwn import *
from Crypto.Util.number import bytes_to_long, long_to_bytes, inverse
import string
import random
import sys
from math import gcd

def get_params():
    r = remote('crypto.chal.csaw.io', 5000)
    banner = r.recvline()
    publine = r.recvline().decode()
    lines = [publine]
    for _ in range(3):
        lines.append(r.recvline().decode())
    r.close()
    # Look for the pubkey in publine
    for l in lines:
        if "public key" in l:
            _, rest = l.split(':', 1)
            p, g, y = [int(x) for x in rest.strip().split()]
            return p, g, y
    raise Exception('Failed to parse public key')

def bsgs(base, target, modulus, upper_bound):
    # Baby-step giant-step to solve x such that base^x = target mod modulus, x <= upper_bound
    from math import isqrt
    m = isqrt(upper_bound) + 1
    table = {}
    e = 1
    for j in range(m):
        table[e] = j
        e = e * base % modulus
    factor = pow(base, modulus-2, modulus)
    factor = pow(factor, m, modulus)
    e = target
    for i in range(m):
        if e in table:
            return (i * m + table[e])
        e = e * factor % modulus
    return None

def find_m(p):
    # find m in range such that hex(m) contains '436973636f'.
    # Try different paddings.
    prefix = b'Cisco'
    for padlen in range(8):
        for pad in range(0, 2**(8*padlen)):
            m = int.from_bytes(prefix + pad.to_bytes(padlen, 'big'), 'big')
            if 1 < m < p-1:
                yield m
    # try with padding before too:
    for padlen in range(1, 4):
        for pad in range(0, 2**(8*padlen)):
            m = int.from_bytes(pad.to_bytes(padlen, 'big') + prefix, 'big')
            if 1 < m < p-1:
                yield m
    # give up after that

def try_forge():
    p, g, y = get_params()
    for m in find_m(p):
        mhex = hex(m)[2:]
        for r in range(2, 1000):
            try:
                rhs = pow(g, m, p) * inverse(pow(y, r, p), p) % p
                s = bsgs(r, rhs, p, 1000000)  # search up to 1 million for s
                if s is not None and 1 < s < p-1:
                    return dict(answer=mhex, r=r, s=s, p=p, g=g, y=y)
            except Exception as ex:
                continue
    return None

def main():
    result = try_forge()
    if not result:
        print('Could not find any valid (m, r, s) triple. Try increasing search range.')
        sys.exit(1)
    print(f"Forged a signature! answer: {result['answer']} r: {result['r']} s: {result['s']}")
    r = remote('crypto.chal.csaw.io', 5000)
    for _ in range(4):
        r.recvline()
    r.sendline(result['answer'].encode())
    r.sendline(str(result['r']).encode())
    r.sendline(str(result['s']).encode())
    response = r.recvall(timeout=5)
    print('Response from server:')
    print(response)

if __name__ == '__main__':
    main()

